const root=document.getElementById('app');
let selectedDate=null,selectedSlot=null,selectionSaved=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function poster(a){return `<div class="poster" style="--bg:${a.bg};--ink:${a.ink}" aria-hidden="true"><div class="poster-inner"><div class="poster-lines"></div><div class="poster-top"><span>APPLIED AI STUDIO</span></div><div class="poster-title"${['hr-studio','review-desk'].includes(a.id)?' style="font-size:25px"':''}>${a.title}</div><div class="poster-subtitle">${a.tagline}</div><div class="poster-shape"></div><div class="poster-symbol">${a.symbol}</div></div><div class="poster-strip"><span>✦</span> ${a.label}</div></div>`}
const applicationDomains = {
 'dispatch-flow':'Operations','stocklist':'Operations','tendersetu':'Business Development',
 'gst-reconciliation':'Finance','mr-wasooli':'Finance','card-scanner':'Sales','minicrm':'Sales',
 'social-media-planner':'Marketing','digital-profile-creator':'Personal Branding','hr-studio':'Human Resources',
 'compliance-calender':'Compliance','yojanasetu':'Business Development','hisabtalk-ai':'Knowledge Management','review-desk':'Engineering & Quality','production-saathi':'Operations'
};
function catalog(selectedDomain='All'){
 document.title='Explore applications | MCCIA AI Studio';
 const domains=['All',...new Set(apps.map(a=>applicationDomains[a.id]))];
 const visibleApps=selectedDomain==='All'?apps:apps.filter(a=>applicationDomains[a.id]===selectedDomain);
 root.innerHTML=`<div class="container"><div class="intro"><div><div class="eyebrow">MCCIA APPLIED AI STUDIO</div><h1>Small business. Meet big possibilities.</h1><p>Discover practical AI applications built for the way you work.</p></div><div class="collection-count" role="status"><b>${visibleApps.length} ${visibleApps.length===1?'application':'applications'}</b> to explore</div></div><div class="domain-filters" role="group" aria-label="Filter applications by domain">${domains.map(domain=>`<button type="button" class="domain-filter ${domain===selectedDomain?'selected':''}" data-domain="${domain}" aria-pressed="${domain===selectedDomain}">${domain}</button>`).join('')}</div><div class="grid">${visibleApps.map(a=>`<a class="card" href="#/apps/${a.id}" aria-label="View ${a.name} details">${poster(a)}<h2>${a.name}</h2><p class="category">${a.category}</p><p>${a.tagline}</p></a>`).join('')}</div><div class="catalog-note"><span class="note-icon" aria-hidden="true">✧</span><div><strong>Find the right AI application for your business.</strong><p>Explore an application to see what it does, who it’s for, and choose a session with the studio.</p></div></div></div>`;
 root.querySelectorAll('[data-domain]').forEach(button=>button.onclick=()=>{catalog(button.dataset.domain);root.querySelector('[data-domain="'+button.dataset.domain+'"]')?.focus({preventScroll:true});});
}
function detail(a){document.title=`${a.name} | MCCIA AI Studio`;root.innerHTML=`<div class="container" style="padding-top:20px;padding-bottom:0"><div class="breadcrumb"><a href="#/">Applications</a><span>/</span><span>${a.name}</span></div></div><section class="detail-hero" style="--hero-accent:${a.ink}"><div class="hero-inner"><div class="detail-poster">${poster(a)}</div><div class="detail-copy"><div class="eyebrow">${a.category}</div><h1>${a.name}</h1><p class="detail-tagline">${a.tagline}</p><div class="audience-box"><small>BUILT FOR</small><strong>${a.audience}</strong></div><p class="detail-meta">AI-powered &nbsp; · &nbsp; Built for MSMEs &nbsp; · &nbsp; MCCIA, Pune</p><a href="#/apps/${a.id}/book" class="primary">Book here <span aria-hidden="true">→</span></a></div></div></section><div class="container detail-body"><section><h2>About the application</h2><p>${a.description}</p><h2 style="margin-top:32px">What you can do</h2><ul class="features">${a.features.map(f=>`<li><span class="check" aria-hidden="true">✓</span>${f}</li>`).join('')}</ul></section><aside class="side-note"><div class="eyebrow">LET’S MAKE AI WORK FOR YOU</div><h3>Build it for your business</h3><p>Book a one-hour app-development session for ${a.name} with MCCIA Applied AI Studio.</p></aside></div>`}
const times=['11:00','12:00','14:30','15:30'];
const timeLabels={'11:00':'11:00 AM – 12:00 PM','12:00':'12:00 PM – 1:00 PM','14:30':'2:30 PM – 3:30 PM','15:30':'3:30 PM – 4:30 PM'};
const dateLabel=d=>new Date(d+'T12:00:00Z').toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',timeZone:'Asia/Kolkata'});
let availability=[],schedule=[],loading=false,bookingError='',receipt=null,bookingBusy=false,requestNumber=0,week=0,activeApp=null;
let contact={name:'',email:'',company:''};
function landing(){document.title='Your next big move | MCCIA AI Studio';root.innerHTML=`<section class="landing"><div class="landing-grid"></div><div class="orb orb-one"></div><div class="orb orb-two"></div><div class="landing-topline"><span>THE MCCIA APPLIED AI STUDIO</span></div><div class="landing-copy"><h1>Less busywork.<br>More <span>possibility.</span></h1><p>${apps.length} practical AI applications.<br>One big leap for your business.</p></div><div class="card-universe" aria-hidden="true">${[apps[0],apps[4],apps[8]].map((a,i)=>`<div class="floating-card float-${i}">${poster(a)}</div>`).join('')}<div class="orbit-label">${apps.length} APPLICATIONS<br><strong>Endless possibilities.</strong></div></div><div class="landing-action"><a class="primary landing-cta" href="#/apps">Find my applications <span>↗</span></a><div class="landing-caption">EXPLORE IT. MAKE IT YOURS. BUILD WHAT’S NEXT.</div></div><div class="landing-bottom"><span>FROM EVERYDAY CHALLENGES</span><div class="ticker"><div>OPERATIONS &nbsp; ✳ &nbsp; FINANCE &nbsp; ✳ &nbsp; MARKETING &nbsp; ✳ &nbsp; SALES &nbsp; ✳ &nbsp; PEOPLE &nbsp; ✳ &nbsp; OPERATIONS &nbsp; ✳ &nbsp; FINANCE &nbsp; ✳ &nbsp; MARKETING &nbsp; ✳ &nbsp; SALES &nbsp; ✳ &nbsp; PEOPLE</div></div><span>TO EXTRAORDINARY PROGRESS ↗</span></div></section>`;}
const originalDetail=detail;
detail=function(a){originalDetail(a);root.querySelector('.breadcrumb a').href='#/apps';const hero=root.querySelector('.detail-hero');hero.style.setProperty('--app-bg',a.bg);hero.style.setProperty('--app-ink',a.ink);hero.insertAdjacentHTML('afterbegin','<div class="hero-mesh" aria-hidden="true"></div>');root.querySelector('.detail-copy').insertAdjacentHTML('beforeend','<div class="hero-promise"><span>01 · Explore the app</span><span>02 · Pick your slot</span><span>03 · Let’s build</span></div>');root.querySelector('.detail-meta').textContent='Made for your business. Built with the studio.';};

function slotSummary(a){return `<div class="session-chip"><span class="mini-icon" style="--bg:${a.bg};--ink:${a.ink}">${a.symbol}</span><div><strong>${a.name}</strong><small>${selectedDate?dateLabel(selectedDate):'App-development session'}${selectedSlot?' · '+timeLabels[selectedSlot]:' · 1 hour'} · IST</small></div></div>`}
function booking(a){activeApp=a;document.title=`Choose your slot | ${a.name}`;const days=schedule.slice(week*5,week*5+5);root.innerHTML=`<div class="booking-shell"><div class="booking-title"><a class="back" href="#/apps/${a.id}">← ${a.name}</a><h1>A little time.<br class="mobile-break"> A big next step.</h1><p>Choose your one-hour app-development session.</p></div><div class="slot-workspace"><section><div class="section-heading"><h2>Pick a day</h2><div class="week-controls"><button id="prev-week" aria-label="Previous days" ${week===0?'disabled':''}>←</button><span>${days.length?dateLabel(days[0].date):'Upcoming days'}</span><button id="next-week" aria-label="Next days" ${(week+1)*5>=schedule.length?'disabled':''}>→</button></div></div><div class="dates">${days.map(d=>`<button class="date ${selectedDate===d.date?'selected':''}" data-day="${d.date}" aria-pressed="${selectedDate===d.date}" ${!d.active?'disabled':''}><span>${new Date(d.date+'T12:00Z').toLocaleDateString('en-IN',{weekday:'short'})}</span><strong>${Number(d.date.slice(-2))}</strong><span>${d.active?'Available':'Inactive'}</span></button>`).join('')}</div>${loading&&!days.length?'<p role="status">Loading the studio schedule…</p>':''}<div class="section-heading"><h2>Make it your time</h2><span class="timezone">IST · 1 hour</span></div><div class="slots">${availability.filter(s=>s.visible!==false).map(t=>`<button class="slot ${selectedSlot===t.time?'selected':''}" data-time="${t.time}" ${!t.available||loading?'disabled':''} aria-pressed="${selectedSlot===t.time}"><span>${timeLabels[t.time]}</span><small>${selectedSlot===t.time?'✓ Selected':t.available?'Available':'Unavailable'}</small></button>`).join('')}</div>${!selectedDate?'<p class="slot-hint">Select a day to reveal the available times.</p>':loading?'<p class="slot-hint" role="status">Checking available times…</p>':availability.length===0?'<p class="slot-hint">No sessions are displayed for this day.</p>':''}${bookingError?`<p class="error" role="alert">${esc(bookingError)} <button id="retry">Try again</button></p>`:''}</section><aside class="slot-aside"><div class="eyebrow">YOUR NEXT CHAPTER</div><h2>${a.name}</h2><p>${a.tagline}</p><div class="aside-orbit" aria-hidden="true">${a.symbol}</div><span>1 hour. Your business. Our studio.</span></aside></div><div class="booking-bottom"><div><strong>${selectedSlot?'Nice choice. Your slot is selected.':'Your next step starts here.'}</strong><small>${selectedSlot?dateLabel(selectedDate)+' · '+timeLabels[selectedSlot]+' IST':'Pick a day and time to continue.'}</small></div><a class="primary ${selectedSlot?'':'disabled-link'}" ${selectedSlot?`href="#/apps/${a.id}/details"`:'aria-disabled="true"'}>Continue <span>→</span></a></div></div>`;
root.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>loadDay(a,b.dataset.day));root.querySelectorAll('[data-time]').forEach(b=>b.onclick=()=>{selectedSlot=b.dataset.time;booking(a);root.querySelector(`[data-time="${selectedSlot}"]`).focus()});root.querySelector('#prev-week').onclick=()=>{week--;booking(a)};root.querySelector('#next-week').onclick=()=>{week++;booking(a)};root.querySelector('#retry')?.addEventListener('click',()=>loadSchedule(a));}
async function api(path,options={}){const r=await fetch('/api/'+path,options);let data;try{data=await r.json()}catch{throw Error('The booking service is not connected yet. Please contact the studio.')}if(!r.ok)throw Error(data.error||'Something went wrong. Please try again.');return data;}
async function loadSchedule(a){const n=++requestNumber;loading=true;bookingError='';booking(a);try{const result=await api('schedule');if(n!==requestNumber)return;schedule=result.days;week=0;}catch(e){if(n===requestNumber)bookingError=e.message}finally{if(n===requestNumber){loading=false;booking(a)}}}
async function loadDay(a,date){const n=++requestNumber;selectedDate=date;selectedSlot=null;availability=[];loading=true;bookingError='';booking(a);try{const data=await api('availability?date='+date);if(n===requestNumber)availability=data.slots;}catch(e){if(n===requestNumber)bookingError=e.message}finally{if(n===requestNumber){loading=false;booking(a)}}}
function finalDetails(a){if(!selectedSlot||!selectedDate){location.hash=`#/apps/${a.id}/book`;return}document.title='One last step | MCCIA AI Studio';root.innerHTML=`<div class="final-shell"><div class="finish-header"><div class="finish-check">✓</div><div class="eyebrow">THE BIG DECISIONS ARE DONE</div><h1>One last step.<br><span>Then we’re on.</span></h1><p>Your app and time are selected. Just tell us who’s joining.</p></div><div class="final-card">${slotSummary(a)}<a class="change-slot" href="#/apps/${a.id}/book">Change slot</a><form id="booking-form"><div class="form-grid"><label>Full name<input required minlength="2" maxlength="100" name="name" autocomplete="name" value="${esc(contact.name)}" placeholder="Your full name"></label><label>Email address<input required type="email" maxlength="254" name="email" autocomplete="email" value="${esc(contact.email)}" placeholder="you@company.com"></label><label class="full-width">Company <span>(optional)</span><input maxlength="150" name="company" autocomplete="organization" value="${esc(contact.company)}" placeholder="Your company"></label></div>${bookingError?`<p class="error" role="alert">${esc(bookingError)}</p>`:''}<button class="primary" ${bookingBusy?'disabled':''}>${bookingBusy?'Confirming…':'Confirm my session'} <span>↗</span></button><p class="form-note">Your slot is reserved only after confirmation. Your details are saved with the booking.</p></form></div></div>`;root.querySelectorAll('input').forEach(i=>i.oninput=()=>contact[i.name]=i.value);root.querySelector('#booking-form').onsubmit=async e=>{e.preventDefault();if(bookingBusy)return;bookingBusy=true;bookingError='';finalDetails(a);try{receipt=await api('bookings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({appId:a.id,date:selectedDate,slot:selectedSlot,...contact})});contact={name:'',email:'',company:''};location.hash=`#/apps/${a.id}/confirmed`;}catch(e){bookingError=e.message;finalDetails(a)}finally{bookingBusy=false;if(!receipt)finalDetails(a)}};}
function confirmed(a){if(!receipt){location.hash='#/apps';return}root.innerHTML=`<div class="container"><div class="success-panel"><div class="success-icon">✓</div><div class="eyebrow">IT’S OFFICIAL</div><h1>Let’s build something great.</h1><p>Your ${a.name} development session is booked.</p>${slotSummary(a)}<p>Reference <strong>${esc(receipt.id.slice(0,8).toUpperCase())}</strong></p><p>For changes: <a href="mailto:aistudio@mcciapune.com">aistudio@mcciapune.com</a></p><a class="primary" href="#/apps">Explore more applications ↗</a></div></div>`;}
let editorToken='',editorDate='',editorMessage='',editorSlots=null;
function editor(){document.title='Studio access | MCCIA AI Studio';root.innerHTML=`<div class="editor-shell"><div class="eyebrow">STUDIO ACCESS</div><h1>Make room for what’s next.</h1><p>Manage the days and times people can book.</p>${!editorToken?`<form id="editor-login" class="editor-login"><h2>Editor sign in</h2><p>Use your studio editor access key.</p><label>Access key<input type="password" name="key" required autocomplete="current-password"></label><button class="primary">Sign in →</button></form>`:`<div class="editor-toolbar"><label>Choose a date<input id="editor-date" type="date" value="${editorDate}" min="${new Date(Date.now()+19800000).toISOString().slice(0,10)}"></label><button class="text-button" id="sign-out">Sign out</button></div><div class="editor-board">${editorSlots?`<div class="section-heading"><h2>${dateLabel(editorDate)}</h2><span>Changes apply to all applications</span></div><form id="editor-save"><div class="day-actions"><button type="button" data-day-action="show">Show day</button><button type="button" data-day-action="hide">Hide day</button><button type="button" data-day-action="activate">Activate day</button><button type="button" data-day-action="deactivate">Deactivate day</button></div><div class="editor-row editor-table-head"><span>One-hour session</span><span>Display</span><span>Active</span></div>${editorSlots.map(s=>`<div class="editor-row"><strong>${timeLabels[s.time]}</strong><label><input type="checkbox" data-visible="${s.time}" ${s.visible?'checked':''} aria-label="Display ${timeLabels[s.time]}"><span>Show</span></label><label><input type="checkbox" data-active="${s.time}" ${s.active?'checked':''} ${s.booked?'disabled':''} aria-label="Activate ${timeLabels[s.time]}"><span>${s.booked?'Booked':'Bookable'}</span></label></div>`).join('')}<p>Hidden slots do not appear to visitors. Inactive slots remain visible but cannot be booked. Existing bookings are preserved.</p><button class="primary">Save availability ✓</button></form>`:'<p>Select a date to manage its four session slots.</p>'}</div>`}${editorMessage?`<p class="editor-message" role="status">${esc(editorMessage)}</p>`:''}</div>`;
root.querySelector('#editor-login')?.addEventListener('submit',async e=>{e.preventDefault();const key=new FormData(e.target).get('key');try{await api('editor/session',{headers:{Authorization:'Bearer '+key}});editorToken=key;editorMessage='';editor()}catch(e){editorMessage=e.message;editor()}});root.querySelector('#sign-out')?.addEventListener('click',()=>{editorToken='';editorSlots=null;editorMessage='';editor()});root.querySelector('#editor-date')?.addEventListener('change',async e=>{editorDate=e.target.value;editorSlots=null;try{const r=await api('editor/availability?date='+editorDate,{headers:{Authorization:'Bearer '+editorToken}});editorSlots=r.slots;editorMessage='';}catch(e){editorMessage=e.message}editor()});root.querySelectorAll('[data-day-action]').forEach(b=>b.onclick=()=>{const action=b.dataset.dayAction;const attr=['show','hide'].includes(action)?'data-visible':'data-active';root.querySelectorAll('['+attr+']').forEach(input=>{if(!input.disabled)input.checked=['show','activate'].includes(action)});});root.querySelector('#editor-save')?.addEventListener('submit',async e=>{e.preventDefault();const button=e.target.querySelector('button');button.disabled=true;const slots=editorSlots.map(s=>({time:s.time,visible:root.querySelector(`[data-visible="${s.time}"]`).checked,active:root.querySelector(`[data-active="${s.time}"]`).checked}));try{await api('editor/availability',{method:'PUT',headers:{'Content-Type':'application/json',Authorization:'Bearer '+editorToken},body:JSON.stringify({date:editorDate,slots})});editorSlots=editorSlots.map(s=>({...s,...slots.find(r=>r.time===s.time)}));editorMessage='Availability saved. Visitors will see the updated schedule.'}catch(e){editorMessage=e.message}editor()});}
function render(){requestNumber++;const parts=location.hash.slice(1).split('/').filter(Boolean);document.body.classList.toggle('is-landing',!parts.length);document.body.classList.toggle('is-booking',['book','details'].includes(parts[2]));document.body.classList.toggle('is-slot-page',parts[2]==='book');if(!parts.length)landing();else if(parts[0]==='editor')editor();else if(parts[0]==='apps'&&parts.length===1)catalog();else{const a=apps.find(a=>a.id===parts[1]);if(a&&parts[0]==='apps'){if(activeApp?.id!==a.id){selectedDate=null;selectedSlot=null;schedule=[];availability=[];receipt=null;}activeApp=a;switch(parts[2]){case undefined:detail(a);break;case 'book':booking(a);if(!schedule.length)loadSchedule(a);break;case 'details':finalDetails(a);break;case 'confirmed':confirmed(a);break;default:location.hash='#/apps';}}else location.hash='#/apps';}window.scrollTo(0,0)}
window.addEventListener('hashchange',render);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_app_booking',title:'Open app development booking',description:'Open an application’s date and time selection. This does not reserve a slot.',inputSchema:{type:'object',properties:{appId:{type:'string',enum:apps.map(a=>a.id)}},required:['appId'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async({appId})=>{if(!apps.some(a=>a.id===appId))throw new Error('Unknown application');history.replaceState(null,'',`#/apps/${appId}/book`);render();return {appId,stage:'select_date_and_time',booked:false}}})).catch(()=>{});}catch{}}
